    final String nombre;
    Pantalla(String nombre) { this.nombre = nombre; }
    public void actualizar(int valor) { System.out.print(nombre + valor + " "); }
}
class Sensor {
    private final List<Observador> observadores = new ArrayList<>();
    void agregar(Observador o) { observadores.add(o); }
    void quitar(Observador o) { observadores.remove(o); }
    void cambiar(int valor) {
        for (Observador o : observadores) o.actualizar(valor);
    }
}
public class Main {
    public static void main(String[] args) {
        Sensor s = new Sensor();
        Pantalla a = new Pantalla("A");
        Pantalla b = new Pantalla("B");
        s.agregar(a); s.agregar(b);
        s.cambiar(1);
        s.quitar(a);
        s.cambiar(2);
    }
}
```

